/**
 * Interactive Reading bank — authored against docs/reading/det-interactive-reading-item-spec.md,
 * which records the measured parameters of all six real DET practice sets.
 *
 * Rules the spec imposes on every set here:
 *   · 110–270 word passage in three blocks — the gap sentence is always the END of the first block
 *   · 7–10 cloze blanks, five options each, at least a third of them FUNCTION words
 *     (copula, relative pronoun, preposition, auxiliary, conjunction) — not just vocabulary
 *   · two highlight questions, at least one answer under 40 characters
 *   · highlight stems drawn from the nine real stem families, never all "where does it mention"
 *   · the select-idea key is a RESTATEMENT of a sentence the passage actually contains
 *   · five Title Case title options, 3–6 words each
 *
 * Genre mix is deliberate: DET's own six sets are one narrative, one first-person opinion and
 * four informational, so a bank of only academic passages would not rehearse the real task.
 */
