      "Over the following year the same crack appeared in every profile they plotted, and it lined up with the places {5} undersea earthquakes were recorded. The rift was real, and it was evidence for continental drift — an idea most geologists then treated as nonsense. It took another decade {6} the profession changed its mind. Tharp's name was left off the first published map; the credit {7} to Heezen. She kept working anyway, and by the time she died in 2006 the maps she drew {8} on the wall of almost every earth-science department in the world.",
