    gapAfter: 2,
    paragraphs: [
      "On a summer night a large city can be five degrees warmer than the fields around it. The reason is not exhaust or air conditioning, {1} they contribute. It is mostly the material the city is made {2}. Brick, asphalt and concrete absorb heat all day and release it slowly after dark, so the city never fully {3} down.",
      "The effect is measurable, and it is not evenly shared. Studies in several countries have found that the hottest districts are, with dull regularity, the poorest ones: fewer trees, less park, more paving, smaller windows. Heat, {4} it turns out, follows the same map as everything else.",
      "Trees are the strongest single measure, because shade and evaporation work together. Pale roofs help, and cost almost nothing {5} a roof is being replaced anyway. Even breaking up long stretches of asphalt with grass makes a difference {6} can be felt on the pavement. None of these measures {7} a ribbon to cut, which is why the districts that need them most are usually the last to {8} them.",
    ],
