      "Nothing about a cup of coffee is obvious from looking at it. It starts as a small red fruit called a coffee cherry, {1} on bushes in warm, mountainous regions where the nights are cool. Workers pick the ripe cherries {2} hand, since a single tree does not ripen all {3} once, and a machine cannot tell a red cherry {4} a green one. Inside each cherry {5} usually two seeds, and it is those seeds — not the fruit around them — {6} we call coffee beans. Getting from that seed to a drink takes {7} more work than most people imagine.",
      "After picking, the beans are dried, then roasted at high heat to bring out their familiar flavor and dark color. Roasters carefully control the time and temperature, since even small changes can make the coffee taste bitter or weak. Finally, the roasted beans are ground and brewed into the drink people enjoy every morning.",
