      "Mangrove roots also form a safe nursery for young fish, crabs, and shrimp before they swim out to the open ocean. During storms, the dense roots absorb some of the force of incoming waves, protecting coastal villages from flooding. Sadly, mangrove forests are being cut down quickly to make room for farms and shrimp ponds.",
