        paragraph: 3,
        whyTh: "คำถามถามผลลัพธ์ จึงไฮไลต์อนุประโยคหลัง While ซึ่งเป็นผลด้านบวก ไม่ใช่ครึ่งหลังที่พูดถึงความกังวลของผู้ขาย",
