    gapAfter: 1,
    paragraphs: [
      "Sign languages are complete, natural languages {1} their own grammar and vocabulary, separate from the spoken languages used in the same country. American Sign Language, for example, has a different word order and structure {2} spoken English. Signers use hand shapes, movement, facial expressions, and body position together {3} communicate meaning. A hearing person watching for the first time often assumes the hands {4} doing all the work. They are not. Change nothing {5} the hands and move the eyebrows, and the same signs become a question; the hands have not moved, {6} the meaning has. This is why a sign cannot be looked {7} the way a word can.",
      "Facial expressions in sign language are not just emotional add-ons — they carry real grammatical information. Raised eyebrows can turn a statement into a yes-or-no question, while a slight head tilt can signal a conditional sentence, similar to using 'if' in English. Learning to read these signals takes years of practice for hearing learners.",
    ],
    blanks: [
      { n: 1, options: ["with", "of", "by", "for", "from"], answer: "with", skillTh: "คำบุพบทแสดงการมี", whyTh: "languages with their own grammar = ภาษาที่มีไวยากรณ์ของตัวเอง · of ตรงนี้จะกลายเป็นความเป็นเจ้าของที่ผิดรูป" },
      { n: 2, options: ["from", "than", "to", "of", "with"], answer: "from", skillTh: "คำคุณศัพท์ + คำบุพบท", whyTh: "different from = ต่างจาก เป็นคู่ตายตัวในภาษาอังกฤษมาตรฐาน · different than พบในภาษาพูดอเมริกัน แต่ข้อสอบยึด from" },
      { n: 3, options: ["to", "for", "by", "of", "with"], answer: "to", skillTh: "to + กริยา บอกจุดประสงค์", whyTh: "to communicate = เพื่อสื่อความหมาย · for ต้องตามด้วยคำนามหรือ -ing" },
      { n: 4, options: ["are", "is", "was", "has", "have"], answer: "are", skillTh: "ความสอดคล้องประธาน-กริยา", whyTh: "ประธาน the hands เป็นพหูพจน์ และเป็น continuous คู่กับ doing จึงใช้ are" },
      { n: 5, options: ["about", "of", "into", "over", "past"], answer: "about", skillTh: "คำบุพบทตามกริยา", whyTh: "change nothing about X = ไม่เปลี่ยนอะไรเกี่ยวกับ X · change nothing of/into ไม่ใช้ในความหมายนี้" },
      { n: 6, options: ["but", "and", "so", "or", "because"], answer: "but", skillTh: "คำเชื่อมแสดงความขัดแย้ง", whyTh: "มือไม่ขยับ “แต่” ความหมายเปลี่ยน — เป็นความขัดแย้งที่เป็นใจความหลักของทั้งย่อหน้า" },
      { n: 7, options: ["up", "on", "over", "into", "after"], answer: "up", skillTh: "กริยาวลี", whyTh: "look up = เปิดค้นในพจนานุกรม · look after = ดูแล look into = สืบสวน คนละความหมายกันทั้งหมด" },
    ],
    gap: [
      { text: "Even small details, like facial expression, can completely change a sentence's meaning.", correct: true, whyTh: "ชี้ให้เห็นว่าสีหน้าสำคัญเป็นพิเศษ ซึ่งตัวอย่างการยักคิ้วและเอียงศีรษะต่อไปช่วยพิสูจน์" },
      { text: "Braille uses raised dots to let blind readers feel written words with their fingers.", correct: false, whyTh: "อักษรเบรลล์เป็นระบบสื่อสารคนละแบบ ใช้สำหรับอ่าน ไม่ใช่การใช้ภาษามือ" },
      { text: "In ASL, the sign for 'interpret' can be made with either one or two hands.", correct: false, whyTh: "รูปแบบของสัญลักษณ์เดียวแคบเกินไป ไม่เกี่ยวกับบทบาทของสีหน้าโดยรวม" },
      { text: "Sign languages are studied by linguists as evidence that language does not require sound.", correct: false, whyTh: "เป็นข้อสรุปเชิงภาษาศาสตร์ ไม่ใช่ประโยคที่อธิบายไวยากรณ์ทางสีหน้าต่อ" },
      { text: "About three hundred different sign languages are used around the world today.", correct: false, whyTh: "ใส่ตัวเลขเจาะจงที่บทอ่านไม่เคยให้ และไม่ได้พาไปสู่เรื่องสีหน้าที่กล่าวต่อ" },
    ],
