      "Volcanic ash can travel thousands of kilometers on the wind, disrupting flights and covering distant towns in fine gray dust. Meanwhile, the lava that flows near the eruption site slowly cools and hardens into new rock. Over centuries, this process can build entire mountains and even new islands.",
