        answer: "The body's internal clock",
        paragraph: 1,
        whyTh: "เฉลยสั้นแค่วลีนามที่ชี้ตัวสิ่งนั้น ไม่ต้องลากอนุประโยค which controls sleep and hunger ซึ่งเป็นคำขยาย",
