      "European players gradually changed the rules over several centuries, giving the queen and bishop the powerful long-range moves they have today. These changes, completed by around the fifteenth century, made the game faster and more aggressive than its ancient ancestor. Chess has remained largely unchanged since then, played today in almost every country in the world.",
