      "Once the water reached a city, it filled public fountains, baths, and even private homes of wealthy citizens. Roman engineers measured the slope so carefully that water sometimes traveled over fifty miles before losing much pressure. Many of these structures were built so well that a few aqueducts remained partly in use for centuries after Rome itself declined.",
