      "Whale songs are long, repeating patterns of sound {1} by male humpback whales, especially during the breeding season. They are not random noise: each song {2} built from short phrases arranged in a fixed order, and the singer returns to the beginning once the sequence {3} to an end. A single song can last over twenty minutes and may be repeated {4} hours without pause. Water carries low sounds far better {5} air does, so these sounds travel astonishing distances underwater, sometimes reaching other whales many kilometers away. A listener {6} the deck of a boat hears almost nothing, {7} a microphone lowered below the surface reveals a performance {8} can go on all night.",
      "Researchers have noticed that whales within the same region often sing nearly identical songs, and that these songs slowly change over months and years, almost like a shared cultural trend. No one fully agrees on the songs' exact purpose, though most scientists suspect they help attract mates or signal a male's presence to rivals.",
