    gapAfter: 1,
    paragraphs: [
      "Long before alphabets existed, ancient writing systems used hundreds or even thousands of symbols, each one standing {1} a whole word or idea. A scribe had to memorise every sign separately, {2} an unfamiliar one could not be {3} out from its shape. Learning to write this way took years of training and {4} mostly limited to professional scribes, {5} worked for temples, palaces and traders. Writing was therefore a kind of property, owned {6} the {7} people who could do it, and everyone else depended on them. Around 1900 BCE, workers in the Sinai region — miners and labourers, not scholars — {8} up with a radically simpler idea.",
      "Instead of a symbol for every word, they used a small set of signs, each representing a single sound. This early alphabet needed only about twenty-two characters to write any word in the language, and it eventually influenced the Phoenician, Greek, and Latin alphabets that followed. Because there were so few symbols to memorize, far more people could learn to read and write.",
    ],
