        questionTh: "การที่ผีเสื้อราชามีอายุเพียงไม่กี่สัปดาห์หรือไม่กี่เดือน ส่งผลอย่างไร?",
        answer: "it takes several generations to finish the journey north again in spring",
        paragraph: 3,
        whyTh: "คำถามถามผลลัพธ์ จึงไฮไลต์อนุประโยคหลัง Because ซึ่งเป็นผล ไม่ใช่ส่วนหน้าที่บอกว่าอายุสั้น (นั่นคือเหตุ)",
