    gapAfter: 1,
    paragraphs: [
      "Before the late 1800s, towns often set their clocks {1} to the exact position of the sun overhead, so noon in one town could be several minutes different {2} noon in a town just down the road. Nobody minded {3} long as a journey took days: a traveller simply reset a pocket watch on arrival. Railways changed that. Trains crossed several towns {4} an hour, and a timetable printed in one town {5} wrong in the next. Worse, two trains sharing a single track could each believe {6} were running on time. The railways therefore needed reliable, matching schedules {7} avoid collisions, {8} the old local clocks could not provide.",
      "In 1884, an international conference agreed to divide the world into twenty-four standard time zones, each based on its distance from a reference line in Greenwich, England. Countries were free to adjust the exact borders of their zones for political or practical reasons, which is why some zones today follow oddly shaped national borders instead of neat straight lines.",
    ],
