      "Some smaller glaciers in the Alps and Andes have already disappeared entirely within a single generation. As ice loss accelerates, rivers that once flowed steadily throughout the year now experience unpredictable surges followed by dangerous shortages. Scientists warn that millions of people downstream could eventually face serious water insecurity as this trend continues.",
