      "By the eleventh century, Chinese sailors had begun using compasses to navigate the open sea, especially on cloudy nights when the stars were hidden. The technology then spread along trade routes to the Middle East and Europe, where sailors quickly adopted it for their own long ocean voyages. Without the compass, many of history's most famous explorations might never have been possible.",
