    gap: [
      { text: "Subsequent research would ultimately settle this decades-long dispute in a rather decisive fashion.", correct: true, whyTh: "เชื่อมโยงความกังขาของไอน์สไตน์กับการพิสูจน์ยืนยันด้วยการทดลองที่อธิบายต่อไป" },
      { text: "The uncertainty principle states that a particle's position and momentum cannot both be measured with arbitrary precision.", correct: false, whyTh: "เป็นหลักการควอนตัมจริงแต่คนละเรื่อง ไม่เกี่ยวกับข้อถกเถียงเรื่องตัวแปรที่ซ่อนอยู่ของการพัวพัน" },
      { text: "In 2015, a Dutch team closed the last major loophole in a landmark Bell-test experiment conducted over a distance of 1.3 kilometers.", correct: false, whyTh: "เป็นการทดลองเฉพาะเจาะจงครั้งเดียว แคบเกินไปที่จะเปิดประเด็นการยุติข้อถกเถียงโดยรวม" },
      { text: "Quantum entanglement is frequently invoked in popular science writing as an illustration of quantum weirdness.", correct: false, whyTh: "พูดถึงวิธีที่แนวคิดนี้ถูกนำเสนอในวงกว้าง แทนที่จะเล่าการยุติข้อถกเถียงทางวิทยาศาสตร์ต่อ" },
      { text: "The question of hidden variables has never been put to a serious experimental test.", correct: false, whyTh: "ขัดกับย่อหน้าถัดไปที่บอกว่ามีการทดลองอย่างเข้มงวดมานานหลายทศวรรษ" },
    ],
