      "Still, the response has been unusually constructive. Pre-registration now obliges researchers to state their hypotheses and analyses before the data exist, registered reports commit journals to publish on the strength of a design rather than a result, and replication has begun to count as a career-worthy contribution instead of unimaginative housekeeping.",
